`timescale 1ns/1ps

// Eight independent, non-FMA binary32 lanes. The three project-local Xilinx
// floating_point IP types are generated by tb/create_fp_ip.tcl. Each accepts
// one sample per clock: 8 signed-int conversions, 16 multiplies and 8 adds.
// Input tags include reserved result/trace slots; no return backpressure.
module tm4tn8_fp_restore_v1 (
  input  logic          clk,
  input  logic          rst_n,
  input  logic          in_valid,
  input  logic [191:0]  in_tag,
  input  logic [167:0]  in_dot21,
  input  logic [255:0]  in_old_ps,
  input  logic [31:0]   in_sa,
  input  logic [255:0]  in_sw,
  output logic          out_valid,
  output logic [191:0]  out_tag,
  output logic [9:0]    out_tile,
  output logic [7:0]    out_lane_mask,
  output logic [7:0]    out_bad_mask,
  output logic [23:0]   out_phase,
  output logic [255:0]  out_next_ps,
  output logic          out_trace,
  output logic [1:0]    out_trace_slot,
  output logic [255:0]  out_trace_payload,
  output logic          protocol_error
);
  // Tag bits {63,4:0} result slot, 5:6 trace slot, 7 trace enabled,
  // 8:10 selected lane, 11:16 group, 17:25 tile, 26:27 row,
  // 28:35 effective lane mask; higher bits carry task/epoch identity.
  // The generated IP is checked against these values in create_fp_ip.tcl.
  localparam int FP1_LATENCY = 6;
  localparam int FP2_LATENCY = 6;
  logic valid_a, valid_c, valid_add;
  logic [191:0] tag_a, tag_add;
  logic [255:0] old_a, sw_a, dot_a, old_add;
  logic [31:0] sa_a;
  logic [23:0] phase_a;
  typedef struct packed {
    logic [191:0] tag;
    logic [255:0] old_ps;
    logic [255:0] sw;
    logic [255:0] dot;
    logic [31:0] sa;
    logic [23:0] phase;
  } fp_meta_t;
  fp_meta_t meta_1 [0:FP1_LATENCY-1], meta_c;
  fp_meta_t meta_2 [0:FP2_LATENCY-1];
  logic [FP1_LATENCY-1:0] valid_1;
  logic [FP2_LATENCY-1:0] valid_2;
  logic [255:0] dot_float_wire, scale_product_wire;
  logic [255:0] dot_float_c, scale_product_c;
  logic [255:0] scale_product_2 [0:FP2_LATENCY-1];
  logic [255:0] term_wire, term_add, add_wire;
  logic convert_valid [0:7], scale_valid [0:7], term_valid [0:7];
  logic add_valid [0:7];
  logic [191:0] meta_tag [0:34];
  logic [7:0] meta_mask [0:34];
  logic [23:0] meta_phase [0:34];
  logic [255:0] meta_trace [0:34];
  logic [5:0] fifo_slot [0:31];
  logic [4:0] fifo_wr, fifo_rd;
  logic [5:0] fifo_count;
  logic [5:0] head_slot, safe_head_slot, write_slot;
  logic pop;

  function automatic logic finite_f32(input logic [31:0] value);
    return value[30:23] != 8'hff;
  endfunction
  function automatic logic nonnegative_f32(input logic [31:0] value);
    return finite_f32(value) && (!value[31] || value[30:0] == 0);
  endfunction

  always_comb begin
    for (int lane=0; lane<8; lane++)
      phase_a[lane*3 +: 3] =
          nonnegative_f32(sa_a) &&
          nonnegative_f32(sw_a[lane*32 +: 32]) ? 3'd4 : 3'd0;
  end

  for (genvar lane=0; lane<8; lane++) begin : fp_lane
    wire [31:0] signed_dot = dot_a[lane*32 +: 32];
    wire [31:0] sw = sw_a[lane*32 +: 32];
    wire [31:0] mul2_a =
        meta_c.phase[lane*3 +: 3] == 3'd4 ?
        dot_float_c[lane*32 +: 32] : 32'd0;
    wire [31:0] mul2_b =
        meta_c.phase[lane*3 +: 3] == 3'd4 ?
        scale_product_c[lane*32 +: 32] : 32'd0;
    wire [31:0] add_a = term_add[lane*32 +: 32];
    wire [31:0] add_b = old_add[lane*32 +: 32];
    tm1tn8_sitofp_ip convert_dot (
      .aclk(clk), .aresetn(rst_n),
      .s_axis_a_tvalid(valid_a), .s_axis_a_tdata(signed_dot),
      .m_axis_result_tvalid(convert_valid[lane]),
      .m_axis_result_tdata(dot_float_wire[lane*32 +: 32]));
    tm1tn8_fmul_ip multiply_scales (
      .aclk(clk), .aresetn(rst_n),
      .s_axis_a_tvalid(valid_a), .s_axis_a_tdata(sa_a),
      .s_axis_b_tvalid(valid_a), .s_axis_b_tdata(sw),
      .m_axis_result_tvalid(scale_valid[lane]),
      .m_axis_result_tdata(scale_product_wire[lane*32 +: 32]));
    tm1tn8_fmul_ip multiply_dot (
      .aclk(clk), .aresetn(rst_n),
      .s_axis_a_tvalid(valid_c), .s_axis_a_tdata(mul2_a),
      .s_axis_b_tvalid(valid_c), .s_axis_b_tdata(mul2_b),
      .m_axis_result_tvalid(term_valid[lane]),
      .m_axis_result_tdata(term_wire[lane*32 +: 32]));
    tm1tn8_fadd_ip add_ps (
      .aclk(clk), .aclken(1'b1), .aresetn(rst_n),
      .s_axis_a_tvalid(valid_add), .s_axis_a_tdata(add_a),
      .s_axis_b_tvalid(valid_add), .s_axis_b_tdata(add_b),
      .m_axis_result_tvalid(add_valid[lane]),
      .m_axis_result_tdata(add_wire[lane*32 +: 32]));
  end

  assign pop = (fifo_count != 0) && add_valid[0];
  assign head_slot = fifo_slot[fifo_rd];
  assign safe_head_slot = head_slot < 6'd35 ? head_slot : 6'd0;
  assign write_slot = {meta_2[FP2_LATENCY-1].tag[63],
                       meta_2[FP2_LATENCY-1].tag[4:0]};
  always_comb begin
    out_valid = pop && !protocol_error && fifo_count != 0 &&
                head_slot < 6'd35;
    out_tag = meta_tag[safe_head_slot];
    out_tile = {out_tag[161], out_tag[25:17]};
    out_lane_mask = meta_mask[safe_head_slot];
    out_trace = out_tag[7];
    out_trace_slot = out_tag[6:5];
    out_bad_mask = 0;
    out_phase = meta_phase[safe_head_slot];
    out_next_ps = add_wire;
    out_trace_payload = meta_trace[safe_head_slot];
    out_trace_payload[191:160] =
        add_wire[out_tag[10:8]*32 +: 32];
    out_trace_payload[255:224] =
        (out_phase[out_tag[10:8]*3 +: 3] == 3'd4);
    for (int lane=0; lane<8; lane++) begin
      if (out_lane_mask[lane]) begin
        if (out_phase[lane*3 +: 3] == 3'd4 &&
            !finite_f32(add_wire[lane*32 +: 32]))
          out_phase[lane*3 +: 3] = 3'd3;
        if (out_phase[lane*3 +: 3] != 3'd4)
          out_bad_mask[lane] = 1;
      end
    end
    out_trace_payload[255:224] =
        (out_phase[out_tag[10:8]*3 +: 3] == 3'd4);
  end

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      valid_a <= 0;
      valid_c <= 0;
      valid_add <= 0;
      valid_1 <= '0;
      valid_2 <= '0;
      fifo_wr <= 0;
      fifo_rd <= 0;
      fifo_count <= 0;
      protocol_error <= 0;
    end else begin
      valid_a <= in_valid;
      if (in_valid) begin
        tag_a <= in_tag;
        old_a <= in_old_ps;
        sa_a <= in_sa;
        sw_a <= in_sw;
        for (int lane=0; lane<8; lane++)
          dot_a[lane*32 +: 32] <=
              {{11{in_dot21[lane*21+20]}},in_dot21[lane*21 +: 21]};
      end
      valid_1[0] <= valid_a;
      if (valid_a) begin
        meta_1[0].tag <= tag_a;
        meta_1[0].old_ps <= old_a;
        meta_1[0].sa <= sa_a;
        meta_1[0].sw <= sw_a;
        meta_1[0].dot <= dot_a;
        meta_1[0].phase <= phase_a;
      end
      for (int stage=1; stage<FP1_LATENCY; stage++) begin
        valid_1[stage] <= valid_1[stage-1];
        if (valid_1[stage-1]) meta_1[stage] <= meta_1[stage-1];
      end
      valid_c <= valid_1[FP1_LATENCY-1];
      if (valid_1[FP1_LATENCY-1]) begin
        meta_c <= meta_1[FP1_LATENCY-1];
        dot_float_c <= dot_float_wire;
        scale_product_c <= scale_product_wire;
        for (int lane=0; lane<8; lane++) begin
          if (convert_valid[lane] !== 1'b1 ||
              scale_valid[lane] !== 1'b1) protocol_error <= 1;
        end
      end
      valid_2[0] <= valid_c;
      if (valid_c) begin
        meta_2[0] <= meta_c;
        scale_product_2[0] <= scale_product_c;
      end
      for (int stage=1; stage<FP2_LATENCY; stage++) begin
        valid_2[stage] <= valid_2[stage-1];
        if (valid_2[stage-1]) begin
          meta_2[stage] <= meta_2[stage-1];
          scale_product_2[stage] <= scale_product_2[stage-1];
        end
      end
      valid_add <= valid_2[FP2_LATENCY-1];
      if (valid_2[FP2_LATENCY-1]) begin
        tag_add <= meta_2[FP2_LATENCY-1].tag;
        for (int lane=0; lane<8; lane++) begin
          if (term_valid[lane] !== 1'b1) protocol_error <= 1;
          term_add[lane*32 +: 32] <=
              meta_2[FP2_LATENCY-1].phase[lane*3 +: 3] == 3'd4 &&
              finite_f32(scale_product_2[FP2_LATENCY-1][lane*32 +: 32]) &&
              finite_f32(term_wire[lane*32 +: 32]) ?
              term_wire[lane*32 +: 32] : 32'd0;
          old_add[lane*32 +: 32] <=
              meta_2[FP2_LATENCY-1].phase[lane*3 +: 3] == 3'd4 &&
              finite_f32(scale_product_2[FP2_LATENCY-1][lane*32 +: 32]) &&
              finite_f32(term_wire[lane*32 +: 32]) ?
              meta_2[FP2_LATENCY-1].old_ps[lane*32 +: 32] : 32'd0;
        end
      end
      if (valid_2[FP2_LATENCY-1]) begin
        if (fifo_count == 32 && !pop) protocol_error <= 1;
        if (write_slot >= 6'd35) protocol_error <= 1;
        fifo_slot[fifo_wr] <= write_slot;
        fifo_wr <= fifo_wr + 5'd1;
        if (write_slot < 6'd35) begin
        meta_tag[write_slot] <=
            meta_2[FP2_LATENCY-1].tag;
        meta_mask[write_slot] <=
            meta_2[FP2_LATENCY-1].tag[35:28];
        for (int lane=0; lane<8; lane++)
          meta_phase[write_slot][lane*3 +: 3] <=
              meta_2[FP2_LATENCY-1].phase[lane*3 +: 3] != 3'd4 ?
              meta_2[FP2_LATENCY-1].phase[lane*3 +: 3] :
              !finite_f32(scale_product_2[FP2_LATENCY-1][lane*32 +: 32]) ? 3'd1 :
              !finite_f32(term_wire[lane*32 +: 32]) ? 3'd2 : 3'd4;
        meta_trace[write_slot][31:0] <=
            meta_2[FP2_LATENCY-1].dot[
                meta_2[FP2_LATENCY-1].tag[10:8]*32 +: 32];
        meta_trace[write_slot][63:32] <=
            meta_2[FP2_LATENCY-1].sa;
        meta_trace[write_slot][95:64] <=
            meta_2[FP2_LATENCY-1].sw[
                meta_2[FP2_LATENCY-1].tag[10:8]*32 +: 32];
        meta_trace[write_slot][127:96] <=
            scale_product_2[FP2_LATENCY-1][
                meta_2[FP2_LATENCY-1].tag[10:8]*32 +: 32];
        meta_trace[write_slot][159:128] <=
            term_wire[meta_2[FP2_LATENCY-1].tag[10:8]*32 +: 32];
        meta_trace[write_slot][191:160] <= 0;
        meta_trace[write_slot][223:192] <=
            {25'd0,meta_2[FP2_LATENCY-1].tag[160],meta_2[FP2_LATENCY-1].tag[16:11]};
        meta_trace[write_slot][255:224] <= 0;
        end
      end
      if (pop) begin
        if (fifo_count == 0) protocol_error <= 1;
        fifo_rd <= fifo_rd + 5'd1;
        for (int lane=1; lane<8; lane++)
          if (add_valid[lane] !== add_valid[0]) protocol_error <= 1;
      end
      fifo_count <= fifo_count +
          (valid_2[FP2_LATENCY-1] ? 6'd1 : 6'd0) -
          (pop ? 6'd1 : 6'd0);
    end
  end
endmodule
